import numpy as np
from scipy.optimize import least_squares
def cols(b,gate):
    if gate=='tanh': G=np.tanh(b*t)
    elif gate=='hyp': G=t/(t+b)
    elif gate=='exp': G=1-np.exp(-b*t)
    return np.c_[np.ones_like(t),G,P,t*P,P**2,t*P**2,G*P,G*P**2,P**3,G*P**3,t**2*P,t**2]
