            A=cols(x[0],gate); co=np.linalg.lstsq(A,dP_dt,rcond=None)[0]; return dP_dt-A@co
        try:
            r=least_squares(f,[b0],bounds=(1e-3,50))
            v=np.mean(r.fun**2)/np.var(dP_dt)
